class Solution {
    public boolean areNumbersAscending(String s){
        int previous=-1;
        for(String token:s.split(" "))if(Character.isDigit(token.charAt(0))){
            int current=Integer.parseInt(token);
            if(current<=previous)return false;
            previous=current;
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun areNumbersAscending(s:String):Boolean{
        var previous=-1;
        for(token in s.split(' '))if(token[0].isDigit()){
            val current=token.toInt();
            if(current<=previous)return false;
            previous=current
        };
        return true
    }
}

code.cpp:
class Solution {
    public: bool areNumbersAscending(string s){
        stringstream stream(s);
        string token;
        int previous=-1;
        while(stream>>token)if(isdigit(token[0])){
            int current=stoi(token);
            if(current<=previous)return false;
            previous=current;
        }
        return true;
    }
};
